/* Data center PUE: the Green Grid definition, a fixture generated by an independent
   Python reference, the catalog cases, the identities that follow from the ratio and
   the page contract. No expected number comes from the page itself. */
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const assert = require('node:assert/strict');

const root = path.resolve(__dirname, '..');
const slug = 'data-center-pue-calculator';
const html = fs.readFileSync(path.join(root, 'frontend/tools', slug, 'index.html'), 'utf8');
const startMarker = '/* pue-core:start */';
const endMarker = '/* pue-core:end */';
const start = html.indexOf(startMarker);
const end = html.indexOf(endMarker);
assert.ok(start > -1 && end > start, 'core markers missing');
const coreSource = html.slice(start, end + endMarker.length);
assert.ok(!/document\.|window\./.test(coreSource), 'the core stays free of DOM access');
const sandbox = { module: {} };
vm.createContext(sandbox);
vm.runInContext(coreSource + '\nmodule.exports = PueCore;', sandbox);
const C = sandbox.module.exports;

const near = (actual, expected, label, tolerance) => {
  const limit = tolerance === undefined ? 1e-9 : tolerance;
  assert.ok(Math.abs(actual - expected) <= limit,
    label + ': ' + actual + ' is not within ' + limit + ' of ' + expected);
};
const failure = (input) => {
  try { C.run(input); } catch (error) { return error.message; }
  return null;
};

// ---- Constants and parsing.
assert.equal(C.MIN_TARGET, 1);
assert.equal(C.MAX_TARGET, 20);
assert.equal(C.MAX_VALUE, 1000000000000);
assert.equal(C.parseValue('150000', 'total facility energy', '150000'), 150000);
assert.equal(C.parseValue('150,000', 'total facility energy', '150000'), 150000);
assert.equal(C.parseValue(' 150 000 ', 'total facility energy', '150000'), 150000);
assert.equal(C.parseValue('0.000001', 'IT equipment energy', '100000'), 0.000001);
assert.throws(() => C.parseValue('1e6', 'IT equipment energy', '100000'), /as a number/);
assert.throws(() => C.parseValue('-5', 'IT equipment energy', '100000'), /as a number/);

// ---- The independent Python fixture: 40 loads, both units, many targets.
const fixture = JSON.parse(fs.readFileSync(path.join(root, 'tests/fixtures/pue_vectors.json'), 'utf8'));
assert.ok(fixture.vectors.length >= 40, 'fixture size');
assert.equal(fixture.cases.length, 20, 'fixture carries the catalog cases');
for (const vector of fixture.vectors) {
  const label = vector.name;
  const result = C.run(vector.input);
  for (const field of ['pue', 'dcie', 'overhead', 'overheadShare', 'overheadPerIt',
    'facilityAtTarget', 'againstTarget', 'againstTargetShare']) {
    near(result[field], vector.expected[field], label + ' ' + field, 1e-9);
  }
  assert.equal(result.unit, vector.input.unit, label + ' unit');
  near(result.it, vector.expected.it, label + ' it');
  near(result.facility, vector.expected.facility, label + ' facility');
  near(result.target, vector.expected.target, label + ' target');
}

// ---- The catalog cases, replayed through the documented input shape.
const catalog = JSON.parse(fs.readFileSync(path.join(root, 'frontend/assets/tool-catalog.json'), 'utf8'));
const matches = catalog.tools.filter((tool) => tool.slug === slug);
assert.equal(matches.length, 1, 'slug must exist exactly once');
const entry = matches[0];
assert.equal(entry.name, 'Data Center PUE Calculator');
assert.equal(entry.category, 'IT & Networking');
assert.equal(entry.subcategory, 'Estimation & Calculation');
assert.equal(entry.risk, 'low');
assert.equal(entry.maturity, 'draft');
assert.equal(entry.reviewedAt, null);
assert.equal(entry.listed, true);
assert.equal(entry.legacyCategory, null);
assert.equal(entry.icon, '\u{1F5A5}');
assert.equal(new Set(entry.tags).size, entry.tags.length, 'duplicate tags');
assert.equal(new Set(entry.aliases).size, entry.aliases.length, 'duplicate aliases');
assert.ok(entry.method.length > 800, 'method must document the definition, the parts and the limits');
assert.equal(entry.sources.length, 1);
assert.ok(entry.sources[0].url.startsWith('https://datacenters.lbl.gov/'), 'source host');
assert.ok(entry.sources[0].title.includes('White Paper #49'), 'source title names the paper');
assert.equal(entry.testCases.length, 20, 'catalog case count');
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'golden').length, 7);
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'boundary').length, 3);
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'validation').length, 10);

const publicCount = catalog.tools.filter((tool) => tool.listed).length;
assert.ok(publicCount >= 2065, 'the catalog keeps growing: ' + publicCount);

for (const testCase of entry.testCases) {
  if (testCase.kind === 'validation') {
    assert.equal(failure(testCase.input), testCase.expectedError, testCase.name);
    continue;
  }
  const result = C.run(testCase.input);
  for (const [field, expected] of Object.entries(testCase.expected)) {
    near(result[field], expected, testCase.name + ' ' + field, 1e-9);
  }
}

// ---- Identities that follow from the definition itself.
const base = { unit: 'kwh', it: '125000', facility: '175000', target: '1.3' };
const r = C.run(base);
near(r.pue, 175000 / 125000, 'PUE is the facility energy over the IT energy');
near(r.dcie, 100 / r.pue, 'DCiE is the inverse of PUE in percent');
near(r.dcie + r.overheadShare, 100, 'the IT share and the overhead share fill the total');
near(r.overheadPerIt, r.pue - 1, 'overhead per unit of IT load is PUE minus one');
near(r.overhead, r.facility - r.it, 'overhead is the facility total less the IT load');
near(r.facilityAtTarget, r.it * r.target, 'the target facility figure scales the IT load');
near(r.againstTarget, r.facility - r.facilityAtTarget, 'the target comparison is a difference');
assert.ok(r.pue > 1 && r.overhead > 0 && r.againstTarget > 0, 'a facility with overhead is above 1.0');
assert.equal(r.withinTarget, false);

const noOverhead = C.run({ unit: 'kwh', it: '250', facility: '250', target: '1.0' });
assert.equal(noOverhead.pue, 1, 'no overhead means PUE 1.0');
assert.equal(noOverhead.dcie, 100, 'all energy reaches the IT equipment');
assert.equal(noOverhead.overhead, 0, 'no overhead energy');
assert.equal(noOverhead.againstTarget, 0, 'exactly on a 1.0 target');
assert.equal(noOverhead.withinTarget, true);

const better = C.run({ unit: 'kwh', it: '100', facility: '130', target: '1.5' });
assert.ok(better.againstTarget < 0 && better.withinTarget, 'a facility below target is within it');
assert.equal(better.savingAtTarget, 0, 'no saving is claimed when already under target');
const worse = C.run({ unit: 'kwh', it: '100', facility: '190', target: '1.5' });
assert.ok(worse.againstTarget > 0 && !worse.withinTarget, 'a facility above target is not within it');
near(worse.savingAtTarget, worse.againstTarget, 'the saving is the excess over target');

// ---- Unit labels never change the ratio; separators never change the value.
const asEnergy = C.run({ unit: 'kwh', it: '2,400', facility: '3 600', target: '1.4' });
const asPower = C.run({ unit: 'kw', it: '2400', facility: '3600', target: '1.4' });
near(asEnergy.pue, asPower.pue, 'energy and average power give the same ratio');
near(asEnergy.pue, 1.5, 'the same ratio either way');

// ---- Monotonicity: more overhead, a higher PUE.
let previous = 0;
for (const facility of ['100', '120', '150', '200', '400']) {
  const step = C.run({ unit: 'kwh', it: '100', facility, target: '1.4' });
  assert.ok(step.pue > previous, 'PUE rises with facility energy at a fixed IT load');
  previous = step.pue;
}

// ---- Page contract: shared shell, accessible controls, no runtime foreign APIs.
assert.ok(!/fetch\(|XMLHttpRequest|localStorage|sessionStorage|indexedDB|WebSocket/.test(html), 'network or storage API found');
assert.ok(!/<script[^>]+src="https?:/i.test(html), 'remote script');
assert.ok(!/<link[^>]+href="https?:/i.test(html), 'remote stylesheet');
assert.ok(!/on(?:click|input|change|submit)=/i.test(html), 'inline handler');
assert.ok(!/\beval\s*\(|new\s+Function\b/.test(html), 'unsafe script evaluation');
assert.ok(html.includes('<form id="pue-form" novalidate>'), 'form missing');
assert.ok(html.includes('type="submit"'), 'submit missing');
assert.ok(html.includes('role="alert"'), 'error announcement missing');
assert.ok(html.includes('aria-live="polite" aria-atomic="true"'), 'result region missing');
assert.ok(html.includes('/assets/app.js') && html.includes('/assets/style.css'), 'shared shell assets missing');
for (const id of ['it', 'facility', 'unit', 'target']) {
  assert.ok(html.includes('for="' + id + '"'), 'missing label for ' + id);
  assert.ok(html.includes('id="' + id + '"'), 'missing control ' + id);
}
for (const id of ['pue-form', 'pue-err', 'pue-out', 'it-label', 'facility-label']) {
  assert.ok(html.includes('id="' + id + '"'), 'missing id ' + id);
}
assert.ok(html.includes('<option value="kwh" selected>') && html.includes('<option value="kw">'),
  'unit options missing');
assert.ok(!/style="[^"]*width:\s*\d{3,}px/.test(html), 'fixed wide inline styles');

console.log('data-center-pue: 20 catalog cases, ' + fixture.vectors.length +
  ' reference vectors, identities, unit and page contracts passed');
